var toks=''.split(' ');
console.log('OBSERVED: empty string split produces '+toks.length+' token(s): '+JSON.stringify(toks));
assert(toks.length===1 && toks[0]==='','confirmed: "".split(" ") -> [""]');
assert(''.trim()==='','trim of empty is empty');

var vals=[];
var avg=vals.reduce(function(a,b){return a+b;},0)/vals.length;
console.log('OBSERVED: average of empty array = '+avg);
assert(Number.isNaN(avg),'confirmed: 0/0 is NaN');
assert(avg!==avg,'confirmed: NaN !== NaN, so equality checks cannot catch it');

var rec={a:1,b:undefined,c:null};
var back=JSON.parse(JSON.stringify(rec));
console.log('OBSERVED: keys after round-trip = '+JSON.stringify(Object.keys(back)));
assert(!('b' in back),'confirmed: undefined field dropped silently');
assert('c' in back && back.c===null,'confirmed: null field survives');

var vals=[10,20,Number('abc'),30];
var total=vals.reduce(function(a,b){return a+b;},0);
console.log('OBSERVED: sum containing one NaN = '+total);
assert(Number.isNaN(total),'confirmed: single NaN poisons the whole sum');
assert(typeof total==='number','confirmed: no error thrown, still typeof number');

var a=5/0, b=-5/0;
console.log('OBSERVED: 5/0 = '+a+', -5/0 = '+b);
assert(a===Infinity,'confirmed: 5/0 is Infinity, no error');
assert(b===-Infinity,'confirmed: -5/0 is -Infinity');
assert(isFinite(a)===false,'confirmed: Infinity fails isFinite check');

var a=Math.pow(2,53), b=Math.pow(2,53)+1;
console.log('OBSERVED: 2^53+1 === 2^53 -> '+(b===a));
assert(b===a,'confirmed: 2^53+1 collapses to 2^53');
assert((2n**53n+1n)!==(2n**53n),'control: BigInt keeps them distinct');

var s=0.1+0.2;
console.log('OBSERVED: 0.1+0.2 = '+s);
assert(s!==0.3,'confirmed: 0.1+0.2 !== 0.3');
assert(s===0.30000000000000004,'confirmed: exact binary result');

var recs=[]; for(var i=0;i<1000;i++)recs.push(i);
function page(p,size){return recs.slice((p-1)*size,p*size);} // 1-based pages assumed
var p1=page(1,200);
console.log('OBSERVED: "page 1" first id = '+p1[0]+', length = '+p1.length);
assert(p1[0]===0 && p1.length===200,'confirmed: 1-based math serves records 0..199 as page 1');
var seen={}; [page(1,200),page(2,200)].forEach(function(pg){pg.forEach(function(r){seen[r]=(seen[r]||0)+1;});});
var dup=Object.keys(seen).filter(function(k){return seen[k]>1;});
assert(dup.length===0,'control: consistent 1-based paging has no duplicates');

var s='😀';
console.log('OBSERVED: "😀".length = '+s.length+', slice(0,1) = '+JSON.stringify(s.slice(0,1)));
assert(s.length===2,'confirmed: emoji length is 2 (surrogate pair)');
assert(s.slice(0,1).length===1 && s.slice(0,1)!==s,'confirmed: naive slice corrupts the character');
assert(Array.from(s).length===1,'control: Array.from counts 1 code point');

var a='é', b='é';
console.log('OBSERVED: NFC === NFD -> '+(a===b)+', lengths '+a.length+' vs '+b.length);
assert(a!==b,'confirmed: the two forms are not ===');
assert(a.length===1 && b.length===2,'confirmed: different code-unit lengths');
assert(a.normalize('NFC')===b.normalize('NFC'),'control: normalize() unifies them');

var obj={id:1}; obj.self=obj;
var threw=false, msg='';
try{ JSON.stringify(obj); }catch(e){ threw=true; msg=e.message; }
console.log('OBSERVED: JSON.stringify(circular) threw: '+threw+' ('+msg.slice(0,50)+'...)');
assert(threw,'confirmed: circular structure throws TypeError');
assert(/circular/i.test(msg),'confirmed: error names the circular structure');

var map={};
function insert(r){ map[r.id]=r; } // no duplicate check
insert({id:'JAH-REC-000001',v:'first'});
insert({id:'JAH-REC-000001',v:'second'});
console.log('OBSERVED: map holds v='+JSON.stringify(map['JAH-REC-000001'].v)+', size='+Object.keys(map).length);
assert(map['JAH-REC-000001'].v==='second','confirmed: second silently overwrote first');
assert(Object.keys(map).length===1,'confirmed: only one record survives');

var line='"a","Hello, World","c"';
var naive=line.split(',');
console.log('OBSERVED: naive split field count = '+naive.length);
assert(naive.length===4,'confirmed: naive split breaks on the quoted comma');
function csvSplit(l){var out=[],cur='',q=false; for(var i=0;i<l.length;i++){var c=l[i];
 if(c==='"')q=!q; else if(c===','&&!q){out.push(cur);cur='';} else cur+=c;} out.push(cur); return out;}
assert(csvSplit(line).length===3,'control: quote-aware split yields 3 fields');

var s='aaaaaaaaaaaaaaaaaaaa!'; // 20 a's + non-matching tail
var t0=nowMs(); var r1=/^(a+)+$/.test(s); var tNested=nowMs()-t0;
var t1=nowMs(); var r2=/^a+$/.test(s); var tLinear=nowMs()-t1;
console.log('OBSERVED: nested quantifier '+tNested.toFixed(2)+'ms vs linear '+tLinear.toFixed(3)+'ms');
assert(r1===false && r2===false,'both correctly reject');
assert(tNested>tLinear*10,'confirmed: nested quantifier >10x slower on 21 chars');

var d=new Date(2026,1,31);
console.log('OBSERVED: new Date(2026,1,31) -> '+d.toDateString());
assert(d.getMonth()===2 && d.getDate()===3,'confirmed: rolled over to March 3');
assert(!isNaN(d.getTime()),'confirmed: no error, still a valid date object');

var a=[10,9,80,100].sort();
console.log('OBSERVED: default sort -> '+JSON.stringify(a));
assert(JSON.stringify(a)===JSON.stringify([10,100,80,9]),'confirmed: lexicographic order');
assert(JSON.stringify([10,9,80,100].sort(function(x,y){return x-y;}))===JSON.stringify([9,10,80,100]),'control: comparator sorts numerically');

console.log('OBSERVED: parseInt("0x10")='+parseInt('0x10')+', parseInt("10",8)='+parseInt('10',8));
assert(parseInt('0x10')===16,'confirmed: 0x prefix parsed as hex');
assert(parseInt('10',8)===8,'confirmed: radix 8 parses as octal');
assert(parseInt('010',10)===10,'control: explicit radix 10 is safe');

var out='__A__ and __A__'.replace('__A__','x');
console.log('OBSERVED: '+JSON.stringify(out));
assert(out==='x and __A__','confirmed: only first occurrence replaced');
assert('__A__ and __A__'.replace(/__A__/g,'x')==='x and x','control: /g regex replaces all');

var o={}; o['10']='a'; o['2']='b'; o['1']='c';
var keys=Object.keys(o);
console.log('OBSERVED: key order = '+JSON.stringify(keys));
assert(JSON.stringify(keys)===JSON.stringify(['1','2','10']),'confirmed: integer-like keys sort numerically');
var o2={}; o2['b']='a'; o2['a']='b';
assert(JSON.stringify(Object.keys(o2))===JSON.stringify(['b','a']),'control: string keys keep insertion order');

var threw=false, msg='';
try{ JSON.stringify({cap:10n**15n}); }catch(e){ threw=true; msg=e.message; }
console.log('OBSERVED: threw='+threw+' ('+msg.slice(0,45)+'...)');
assert(threw,'confirmed: BigInt serialization throws TypeError');
assert(/BigInt/.test(msg),'confirmed: error names BigInt');

console.log('OBSERVED: 0===-0 -> '+(0===-0)+', 1/0='+1/0+', 1/-0='+(1/-0));
assert(0===-0,'confirmed: 0 === -0');
assert((1/0)!==(1/-0),'confirmed: division distinguishes them');
assert(Object.is(0,-0)===false,'confirmed: Object.is distinguishes -0');

var a=new Array(3).map(function(){return 1;});
var count=0; a.forEach(function(){count++;});
console.log('OBSERVED: length='+a.length+', forEach callbacks fired='+count);
assert(a.length===3,'confirmed: length is 3');
assert(count===0,'confirmed: no callback fired on holes');
assert(JSON.stringify(Array.from({length:3},function(){return 1;}))==='[1,1,1]','control: Array.from fills properly');

var o={};
o['__proto__'].polluted=true;
console.log('OBSERVED: ({}).polluted = '+({}).polluted+', own key present = '+Object.prototype.hasOwnProperty.call(o,'__proto__'));
assert(({polluted:undefined}).polluted===undefined || true,'setup ok');
var fresh={};
assert(fresh.polluted===true,'confirmed: prototype polluted across objects');
assert(Object.prototype.hasOwnProperty.call(o,'__proto__')===false,'confirmed: no own data property was created');
delete Object.prototype.polluted;
assert(({}).polluted===undefined,'cleanup: prototype restored');

var o=JSON.parse('{"a":1,"a":2}');
console.log('OBSERVED: parsed a = '+o.a+', keys = '+JSON.stringify(Object.keys(o)));
assert(o.a===2,'confirmed: duplicate key last-wins silently');
assert(Object.keys(o).length===1,'confirmed: only one key survives');
